CREATE TABLE IF NOT EXISTS platform_bank_accounts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,bank_name VARCHAR(120)NOT NULL,bank_code VARCHAR(10)NOT NULL,ispb VARCHAR(20)NULL,account_type ENUM('checking','savings','payment','business')NOT NULL,agency_encrypted LONGTEXT NOT NULL,agency_digit VARCHAR(3)NULL,account_encrypted LONGTEXT NOT NULL,account_digit VARCHAR(3)NULL,holder_name VARCHAR(150)NOT NULL,holder_document_encrypted LONGTEXT NOT NULL,person_type ENUM('individual','company')NOT NULL,pix_key_encrypted LONGTEXT NULL,pix_key_type ENUM('cpf','cnpj','email','phone','random')NULL,currency CHAR(3)NOT NULL DEFAULT 'BRL',notes_encrypted LONGTEXT NULL,is_default TINYINT(1)NOT NULL DEFAULT 0,status ENUM('active','inactive')NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,INDEX idx_bank_status(status,is_default),CONSTRAINT fk_bank_creator FOREIGN KEY(created_by)REFERENCES users(id)ON DELETE SET NULL)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS subscription_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,subscription_id BIGINT UNSIGNED NOT NULL,tenant_id BIGINT UNSIGNED NOT NULL,from_plan_id BIGINT UNSIGNED NULL,to_plan_id BIGINT UNSIGNED NULL,from_status VARCHAR(30)NULL,to_status VARCHAR(30)NULL,reason VARCHAR(120)NULL,created_at DATETIME NOT NULL,INDEX idx_sub_history(tenant_id,created_at),CONSTRAINT fk_history_subscription FOREIGN KEY(subscription_id)REFERENCES subscriptions(id))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
